#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Bilnov - Outil de mesure AutoCAD-grade, moteurs geometriques PURS + chemin de donnees. Ajoute snapEngine (snap riche: extremite/milieu/intersection/perpendiculaire/point-sur-ligne + guidage orthogonal), quickMeasure (mesure rapide par rayons vers les murs), et expose les SEGMENTS du plan (worker + cad.ts). ADDITIF: la sortie snap existante est conservee, ZERO regression viewer. 17 tests. Le cablage du viewer suit."""
import base64, os, sys, subprocess
FILES={"src/lib/snapEngine.ts": "", "src/lib/quickMeasure.ts": "", "src/lib/__tests__/snapEngine.test.ts": "", "src/lib/__tests__/quickMeasure.test.ts": "", "src/lib/cad.ts": "", "public/cad/dwg-worker.js": ""}
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(a):
    root,build='.',True; i=0
    while i<len(a):
        if a[i]=='--root': root=a[i+1]; i+=2; continue
        if a[i]=='--no-build': build=False
        i+=1
    return root,build
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! echec (rc=%d)."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:]); print("== Bilnov mesure - moteurs (snap riche + mesure rapide) ==")
    for rel,enc in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p),exist_ok=True); c=d(enc)
        if os.path.exists(p) and open(p,encoding='utf-8').read()==c: print("  = ",rel)
        else: open(p,'w',encoding='utf-8').write(c); print("  + ",rel)
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Bilnov mesure - moteurs (snap riche + mesure rapide) applique. Aucun git push.")
if __name__=='__main__': main()
